1. use crate::{
2.     certificate_authority::{CertificateAuthority, CACHE_TTL, NOT_BEFORE_OFFSET, TTL_SECS},
3.     Error,
4. };
5. use async_trait::async_trait;
6. use http::uri::Authority;
7. use moka::future::Cache;
8. use rand::{thread_rng, Rng};
9. use rcgen::{DistinguishedName, DnType, KeyPair, RcgenError, SanType};
10. use std::sync::Arc;
11. use time::{Duration, OffsetDateTime};
12. use tokio_rustls::rustls::{self, ServerConfig};
13. use tracing::debug;
14. 
15. /// Issues certificates for use when communicating with clients.
16. ///
17. /// Issues certificates for communicating with clients over TLS. Certificates are cached in memory
18. /// up to a max size that is provided when creating the authority. Certificates are generated using
19. /// the `rcgen` crate.
20. ///
21. /// # Examples
22. ///
23. /// ```rust
24. /// use hudsucker::{certificate_authority::RcgenAuthority, rustls};
25. /// use rustls_pemfile as pemfile;
26. ///
27. /// let mut private_key_bytes: &[u8] = include_bytes!("../../examples/ca/hudsucker.key");
28. /// let mut ca_cert_bytes: &[u8] = include_bytes!("../../examples/ca/hudsucker.cer");
29. /// let private_key = rustls::PrivateKey(
30. ///     pemfile::pkcs8_private_keys(&mut private_key_bytes)
31. ///         .unwrap()
32. ///         .remove(0),
33. /// );
34. /// let ca_cert = rustls::Certificate(
35. ///     pemfile::certs(&mut ca_cert_bytes)
36. ///         .unwrap()
37. ///         .remove(0),
38. /// );
39. ///
40. /// let ca = RcgenAuthority::new(private_key, ca_cert, 1_000).unwrap();
41. /// ```
42. #[cfg_attr(docsrs, doc(cfg(feature = "rcgen-ca")))]
43. #[derive(Clone)]
44. pub struct RcgenAuthority {
45.     private_key: rustls::PrivateKey,
46.     ca_cert: rustls::Certificate,
47.     cache: Cache<Authority, Arc<ServerConfig>>,
48. }
49. 
50. impl RcgenAuthority {
51.     /// Attempts to create a new rcgen authority.
52.     ///
53.     /// # Errors
54.     ///
55.     /// This will return an error if the provided key or certificate is invalid, or if the key does
56.     /// not match the certificate.
57.     pub fn new(
58.         private_key: rustls::PrivateKey,
59.         ca_cert: rustls::Certificate,
60.         cache_size: u64,
61.     ) -> Result<RcgenAuthority, Error> {
62.         let ca = Self {
63.             private_key,
64.             ca_cert,
65.             cache: Cache::builder()
66.                 .max_capacity(cache_size)
67.                 .time_to_live(std::time::Duration::from_secs(CACHE_TTL))
68.                 .build(),
69.         };
70. 
71.         ca.validate()?;
72.         Ok(ca)
73.     }
74. 
75.     fn gen_cert(&self, authority: &Authority) -> rustls::Certificate {
76.         let mut params = rcgen::CertificateParams::default();
77.         params.serial_number = Some(thread_rng().gen::<u64>().into());
78. 
79.         let not_before = OffsetDateTime::now_utc() - Duration::seconds(NOT_BEFORE_OFFSET);
80.         params.not_before = not_before;
81.         params.not_after = not_before + Duration::seconds(TTL_SECS);
82. 
83.         let mut distinguished_name = DistinguishedName::new();
84.         distinguished_name.push(DnType::CommonName, authority.host());
85.         params.distinguished_name = distinguished_name;
86. 
87.         params
88.             .subject_alt_names
89.             .push(SanType::DnsName(authority.host().to_owned()));
90. 
91.         let key_pair = KeyPair::from_der(&self.private_key.0).expect("Failed to parse private key");
92.         params.alg = key_pair
93.             .compatible_algs()
94.             .next()
95.             .expect("Failed to find compatible algorithm");
96.         params.key_pair = Some(key_pair);
97. 
98.         let key_pair = KeyPair::from_der(&self.private_key.0).expect("Failed to parse private key");
99. 
100.         let ca_cert_params = rcgen::CertificateParams::from_ca_cert_der(&self.ca_cert.0, key_pair)
101.             .expect("Failed to parse CA certificate");
102.         let ca_cert = rcgen::Certificate::from_params(ca_cert_params)
103.             .expect("Failed to generate CA certificate");
104. 
105.         let cert = rcgen::Certificate::from_params(params).expect("Failed to generate certificate");
106.         rustls::Certificate(
107.             cert.serialize_der_with_signer(&ca_cert)
108.                 .expect("Failed to serialize certificate"),
109.         )
110.     }
111. 
112.     fn validate(&self) -> Result<(), RcgenError> {
113.         let key_pair = rcgen::KeyPair::from_der(&self.private_key.0)?;
114.         rcgen::CertificateParams::from_ca_cert_der(&self.ca_cert.0, key_pair)?;
115.         Ok(())
116.     }
117. }
118. 
119. #[async_trait]
120. impl CertificateAuthority for RcgenAuthority {
121.     async fn gen_server_config(&self, authority: &Authority) -> Arc<ServerConfig> {
122.         if let Some(server_cfg) = self.cache.get(authority).await {
123.             debug!("Using cached server config");
124.             return server_cfg;
125.         }
126.         debug!("Generating server config");
127. 
128.         let certs = vec![self.gen_cert(authority)];
129. 
130.         let mut server_cfg = ServerConfig::builder()
131.             .with_safe_defaults()
132.             .with_no_client_auth()
133.             .with_single_cert(certs, self.private_key.clone())
134.             .expect("Failed to build ServerConfig");
135. 
136.         server_cfg.alpn_protocols = vec![
137.             #[cfg(feature = "http2")]
138.             b"h2".to_vec(),
139.             b"http/1.1".to_vec(),
140.         ];
141. 
142.         let server_cfg = Arc::new(server_cfg);
143. 
144.         self.cache
145.             .insert(authority.clone(), Arc::clone(&server_cfg))
146.             .await;
147. 
148.         server_cfg
149.     }
150. }
