     fn init_ca(cache_size: u64) -> RcgenAuthority {
         let mut private_key_bytes: &[u8] = include_bytes!("../../examples/ca/hudsucker.key");
         let mut ca_cert_bytes: &[u8] = include_bytes!("../../examples/ca/hudsucker.cer");
